void Node::emit_boot(const NodeBoot &e, TimeUs at)
{
    if (sink_ == nullptr) {
        return;
    }
    uint8_t buf[NodeBoot::kMaxSize];
    fr::wire::Writer w(buf, sizeof(buf));
    encode(e, w);
    sink_->event(port_, kEventBoot, Priority::normal, w.bytes(), at, kOrdered);
}

